codeExample.bad:
/* A close button styled at only 20x20 pixels, well under the
   44x44 AAA target size, with no larger alternative offered */
.close-button {
  width: 20px;
  height: 20px;
  padding: 0;
}

codeExample.good:
/* The visible icon can stay small, but the clickable area is
   expanded to meet the 44x44 pixel minimum using padding */
.close-button {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.close-button svg {
  width: 16px;
  height: 16px;
}
